H.background();
const cx = H.W * 0.40, cy = H.H * 0.56, R = Math.min(H.W, H.H) * 0.26;
const M = P.M, Rm = P.R, omega = P.omega;
const I = 0.5 * M * Rm * Rm;                 // solid disk:  I = 1/2 M R^2
const KE = 0.5 * I * omega * omega;          // KE = 1/2 I omega^2
const ang = (omega * t) % H.TAU;             // spins at the real omega, wrapped to one turn
// disk body
H.circle(cx, cy, R, { fill: H.colors.panel, stroke: H.colors.accent, width: 2 });
H.circle(cx, cy, 5, { fill: H.colors.axis });
// spokes rotating at omega so faster spin reads visually
for (let k = 0; k < 8; k++) {
  const a = ang + k * H.TAU / 8;
  H.line(cx, cy, cx + R * Math.cos(a), cy - R * Math.sin(a), { color: H.colors.grid, width: 1.5 });
}
// one highlighted rim marker
H.circle(cx + (R - 6) * Math.cos(ang), cy - (R - 6) * Math.sin(ang), 7, { fill: H.colors.warn });
// energy bar (proportional to KE)
const bx = 28, by = H.H - 42, bw = H.clamp(KE * 1.6, 2, H.W - 60);
H.rect(bx, by, bw, 16, { fill: H.colors.good, radius: 4 });
H.text("KE", bx, by - 6, { color: H.colors.sub, size: 12 });
H.text("Rotational KE:  KE = 1/2 * I * omega^2", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("M = " + M.toFixed(1) + " kg   R = " + Rm.toFixed(2) + " m   omega = " + omega.toFixed(2) + " rad/s", 24, 52, { color: H.colors.sub, size: 13 });
H.text("I = 1/2 M R² = " + I.toFixed(3) + " kg·m²    KE = " + KE.toFixed(2) + " J", 24, 72, { color: H.colors.accent2, size: 13 });
H.legend([{ label: "spinning disk", color: H.colors.accent }, { label: "KE stored", color: H.colors.good }], H.W - 175, 28);
